+      logLevelFilters,
+      showLogLevel,
+      showSource,
+      showTimestamp,
+      sourceFilters,
+      translate,
+    })
+      .filter((line) => line !== "")
+      .join("\n");
+
+  const searchMatchIndices = searchQuery
